      lines: lines([
        ['let osc, fft, frequency;', 'Name the sound, analyzer, and frequency control.'],
        ['let playing = false;', 'Begin silently.'],
        ['const displayGain = 20;', 'Enlarge only the graphs ×20. This does not change the oscillator or its sound level.'],
        ['function setup() {', 'Create one signal and its analysis route.'],
        ['  createCanvas(480, 220);', 'Reserve space for spectrum bars above a waveform.'],
        ["  osc = new p5.Oscillator(440, 'sine');", 'Create a sine signal at 440 Hz.'],
        ['  osc.amp(0.05, 0);', 'Keep the audible signal quiet.'],
        ['  fft = new p5.FFT(256);', 'Use 256 bins to separate nearby frequencies more clearly than 32 bins.'],
        ['  osc.connect(fft);', 'Explicitly send this oscillator to the analyzer while keeping its normal sound output.'],
        ['  frequency = createSlider(110, 2000, 440, 1);', 'Let the listener move the oscillator frequency.'],
        ["  frequency.attribute('aria-label', 'Frequency');", 'Name the frequency control.'],
        ['  frequency.input(() => osc.freq(Number(frequency.value())));', 'Update the oscillator only when the control changes.'],
        ["  createButton('Play').mousePressed(async () => {", 'Use a deliberate gesture to start sound.'],
        ['    await getAudioContext().resume();', 'Wait for the audio context to resume before starting the oscillator.'],
        ['    if (!playing) osc.start();', 'Start once.'],
        ['    playing = true;', 'Record the running state.'],
        ['  });', 'Finish the Play handler.'],
        ["  createButton('Stop').mousePressed(() => {", 'Make a Stop control.'],
        ['    if (playing) osc.stop();', 'Stop the oscillator.'],
        ['    playing = false;', 'Record silence.'],
        ['  });', 'Finish Stop.'],
        ['}', 'Finish setup.'],
        ['function draw() {', 'Read fresh audio analysis for each visual frame.'],
        ['  background(18, 24, 35);', 'Clear the graphs.'],
        ['  const bins = fft.analyze();', 'Read 256 relative spectral amplitudes in the 0–1 range; these are not legacy 0–255 bytes.'],
        ['  const count = Math.min(32, bins.length);', 'Zoom into the first 32 low-frequency bins instead of squeezing the entire spectrum into this plot.'],
        ['  noStroke();', 'Draw bars without outlines.'],
        ['  fill(124, 219, 195);', 'Choose the spectrum color.'],
        ['  for (let i = 0; i < count; i++) {', 'Visit each bin in our low-frequency view.'],
        ['    const bar = constrain(bins[i] * displayGain, 0, 1) * 85;', 'Magnify a quiet measured bin for drawing, then limit the bar to 85 pixels. The source array stays unchanged.'],
        ['    rect(i * width / count, 110 - bar, width / count - 2, bar);', 'Spread the visible bins across the canvas, with bars growing upward from the baseline.'],
        ['  }', 'Finish the spectrum.'],
        ['  const wave = fft.waveform();', 'Read waveform samples, normally between -1 and 1.'],
        ['  noFill();', 'Draw the waveform as an open trace.'],
        ['  stroke(243, 188, 116);', 'Give the time-domain trace a different color.'],
        ['  beginShape();', 'Start connecting sample positions.'],
        ['  for (let i = 0; i < wave.length; i++) {', 'Visit each sample in the current waveform window.'],
        ['    vertex(map(i, 0, wave.length - 1, 0, width), map(constrain(wave[i] * displayGain, -1, 1), -1, 1, 210, 135));', 'Enlarge the signed sample for drawing and clip it to the plot. The original waveform values and audio stay unchanged.'],
        ['  }', 'Finish adding waveform points.'],
        ['  endShape();', 'Draw the connected trace.'],
        ['  noStroke();', 'Return text to a clean outline-free style.'],
        ['  fill(235);', 'Choose a readable text color.'],
        ["  text('Graph ×20 · audio gain 0.05 | ' + (playing ? 'Playing' : 'Silent'), 12, 18);", 'Label the visual magnification separately from the quiet audio gain and playback state.'],
        ['  const binHz = getAudioContext().sampleRate / (2 * bins.length);', 'Divide the highest analyzable frequency, half the sample rate, among the bins. At 48000 samples/second each bin spans 93.75 Hz.'],
        ["  text('Frequency: 0–' + nf(count * binHz, 1, 0) + ' Hz · lower plot: time →', 12, 127);", 'Label the actual frequency window from the browser sample rate. The lower waveform runs left to right in time.'],
        ['}', 'Finish the frame.']
      ])
