      lines: lines([
        ['const base = 235;', 'Use the base frequency of the class ear-training mapping.'],
        ['const ratios = [1, 1.125, 1.25, 1.34, 1.5, 1.67, 1.875, 2];', 'Keep the class scale as the hidden comparison target.'],
        ['let osc, tonic, position;', 'Name the moving oscillator, fixed reference oscillator and pitch control.'],
        ['let playing = false;', 'Begin with no sound.'],
        ['let marks = [];', 'Store the positions you choose by listening.'],
        ['let revealed = false;', 'Hide target marks at first.'],
        ['function setup() {', 'Build the ear practice once.'],
        ['  createCanvas(480, 220);', 'Create a canvas that can be saved as an image.'],
        ["  osc = new p5.Oscillator(base, 'sine');", 'Create the note that will change pitch.'],
        ['  osc.amp(0.025, 0);', 'Keep the moving note quiet.'],
        ["  tonic = new p5.Oscillator(base, 'sine');", 'Create a reference note that stays at 235 Hz while the other note moves.'],
        ['  tonic.amp(0.025, 0);', 'Keep the reference equally quiet; the combined gain stays low.'],
        ['  position = createSlider(0, width, 0, 1);', 'Make an accessible position control for mouse, touch, or keyboard.'],
        ["  position.attribute('aria-label', 'Ear pitch');", 'Name the low-to-high listening control.'],
        ['  position.input(tune);', 'Retune the oscillator when the position changes.'],
        ["  createButton('Start').mousePressed(async () => {", 'Start listening only after a press.'],
        ['    await getAudioContext().resume();', 'Wait for browser audio processing before starting both notes.'],
        ['    tune();', 'Apply the current slider position.'],
        ['    if (!playing) osc.start();', 'Start the moving note once.'],
        ['    if (!playing) tonic.start();', 'Start the fixed reference too, as in the class exercise.'],
        ['    playing = true;', 'Remember that listening is active.'],
        ['  });', 'Finish the Start handler.'],
        ["  createButton('Stop').mousePressed(() => {", 'Offer an immediate way to stop listening.'],
        ['    if (playing) osc.stop();', 'Stop the moving note.'],
        ['    if (playing) tonic.stop();', 'Stop its reference at the same time.'],
        ['    playing = false;', 'Record silence.'],
        ['  });', 'Finish Stop.'],
        ["  createButton('Lower').mousePressed(() => nudge(-2));", 'Move a small step down without requiring precise dragging.'],
        ["  createButton('Higher').mousePressed(() => nudge(2));", 'Move a small step up.'],
        ["  createButton('Mark').mousePressed(() => {", 'Let the listener record a position.'],
        ['    if (!revealed && marks.length < ratios.length) marks.push(Number(position.value()));', 'Record up to eight choices before revealing the targets.'],
        ['  });', 'Finish Mark.'],
        ["  createButton('Reveal').mousePressed(() => { revealed = true; });", 'Reveal the target positions only on request.'],
        ["  createButton('Reset marks').mousePressed(() => { marks = []; revealed = false; });", 'Start a fresh attempt with targets hidden again.'],
        ["  createButton('Save practice image').mousePressed(() => saveCanvas('ear-practice', 'png'));", 'Download this practice canvas; use the official tool for the class’s requested best result.'],
        ['}', 'Finish setup.'],
        ['function tune() {', 'Define the class’s linear position-to-frequency mapping.'],
        ['  osc.freq(base * (1 + Number(position.value()) / width));', 'Map the left edge to 235 Hz and the right edge to 470 Hz.'],
        ['}', 'Finish retuning.'],
        ['function nudge(amount) {', 'Accept a signed movement amount.'],
        ['  position.value(constrain(Number(position.value()) + amount, 0, width));', 'Keep the new position within the canvas range.'],
        ['  tune();', 'Apply the changed position to the sound.'],
        ['}', 'Finish the small-step control.'],
        ['function draw() {', 'Draw the current attempt without exposing targets prematurely.'],
        ['  background(18, 24, 35);', 'Clear the image.'],
        ['  stroke(130);', 'Choose a neutral baseline color.'],
        ['  line(0, 130, width, 130);', 'Draw the low-to-high listening axis.'],
        ['  stroke(243, 188, 116);', 'Use amber for the listener’s marks.'],
        ['  for (let x of marks) line(x, 110, x, 150);', 'Draw each recorded choice.'],
        ['  if (revealed) {', 'Only enter this block after Reveal.'],
        ['    stroke(124, 219, 195);', 'Use green for the comparison targets.'],
        ['    for (let ratio of ratios) {', 'Visit the eight target ratios.'],
        ['      const x = (ratio - 1) * width;', 'Invert the linear mapping to find each target’s horizontal position.'],
        ['      line(x, 80, x, 175);', 'Draw each revealed target.'],
        ['    }', 'Finish drawing targets.'],
        ['  }', 'Finish the reveal-only block.'],
        ['  noStroke();', 'Use clean text.'],
        ['  fill(235);', 'Set the text color.'],
        ["  text('Practice marks: ' + marks.length + '/8 — ' + (playing ? 'listening' : 'silent'), 15, 30);", 'Label this as a practice attempt and show its state.'],
        ["  text(revealed ? 'Amber: your choices. Green: class ratios.' : 'Listen and Mark. Targets hidden until Reveal.', 15, 55);", 'Describe the visible evidence without pretending it is an official grade.'],
        ['}', 'Finish the frame.']
      ])
